def process_student_records(records):
    sorted_records = sorted(records, key=lambda x: x['grade'], reverse=True)
    grade_counts = {}
    for record in sorted_records:
        grade = record['grade']
        grade_counts[grade] = grade_counts.get(grade, 0) + 1
    tied_count = 0
    for count in grade_counts.values():
        if count >= 2:
            tied_count += 1
    stats = {'tied_grades': tied_count}
    return {'sorted': sorted_records, 'stats': stats}
